def _clean(v):
    if v is None:return ""
    try:
        if pd.isna(v):return ""
    except Exception:pass
    t=str(v).strip(); return "" if t.lower() in {"nan","none","null"} else t

def _bool(v): return v if isinstance(v,bool) else _clean(v).lower() in {"1","true","t","yes","y","on"}
def _num(v):
    try:
        if v is None or pd.isna(v):return None
        x=float(v);return x if math.isfinite(x) else None
    except Exception:return None
def _now():return datetime.now(timezone.utc).isoformat()
def _json(v):return json.dumps(v,sort_keys=True,separators=(",",":"),ensure_ascii=False,default=str)
def _hash(v):return hashlib.sha256(_json(v).encode()).hexdigest()
def _id(prefix,v):return prefix+_hash(v)[:24]
def _empty(obj):return pd.DataFrame(columns=obj["required_columns"])
def _canon(v):
    n=_num(v)
    if n is not None:return str(int(n)) if n.is_integer() else format(n,".12g")
    return _clean(v)
def compute_input_hash(path):
    if not path:return "empty"
    p=Path(path)
    if not p.exists():return "missing"
    try:return hashlib.sha256(p.read_bytes()).hexdigest()
    except Exception:return "unreadable"
def normalize_v552_status(status):return _clean(status)
