def validate_v552_v551_input_contract(atoms,directional_coverage=None,directional_adjudication=None,*,run_id=""):
    cov_sup=directional_coverage is not None; adj_sup=directional_adjudication is not None
    cov=directional_coverage if cov_sup else pd.DataFrame(); adj=directional_adjudication if adj_sup else pd.DataFrame(); errs=[]
    for name,frame,required,sup in [("atoms",atoms,V551_ATOM_REQUIRED_COLUMNS,True),("coverage",cov,V551_COVERAGE_REQUIRED_COLUMNS,cov_sup),("adjudication",adj,V551_ADJUDICATION_REQUIRED_COLUMNS,adj_sup)]:
        if sup:
            miss=sorted(set(required)-set(frame.columns))
            if miss:errs.append(f"{name}_missing_columns:{','.join(miss)}")
    if not atoms.empty and not cov_sup:errs.append("directional_distribution_coverage_required")
    if not atoms.empty and not adj_sup:errs.append("directional_candidate_adjudication_required")
    if errs:return {"status":"BLOCKED_V552_V551_V3_INPUT_CONTRACT","errors":errs,"atom_rows":len(atoms),"coverage_rows":len(cov),"adjudication_rows":len(adj),"schema_version":V552_SCHEMA_VERSION}
    for name,frame in [("atoms",atoms),("coverage",cov),("adjudication",adj)]:
        if not frame.empty:
            if not frame.schema_version.astype(str).eq(V551_SCHEMA_VERSION).all() or not frame.compiler_version.astype(str).eq(V551_COMPILER_VERSION).all():errs.append(f"{name}_schema_or_compiler_not_v3")
            if run_id and {_clean(x) for x in frame.run_id if _clean(x)}!={run_id}:errs.append(f"{name}_run_identity_mismatch")
    if not atoms.empty and atoms.atom_id.astype(str).duplicated().any():errs.append("duplicate_atom_id")
    if not cov.empty and cov.empirical_distribution_id.astype(str).duplicated().any():errs.append("duplicate_coverage_distribution")
    if not adj.empty and adj.candidate_id.astype(str).duplicated().any():errs.append("duplicate_adjudication_candidate")
    for r in cov.to_dict("records"):
        a=int(_num(r.get("applicable_candidate_count")) or 0);p=int(_num(r.get("promotable_candidate_count")) or 0);n=int(_num(r.get("nonpromotable_candidate_count")) or 0);d=_clean(r.get("empirical_distribution_id"))
        if a!=p+n:errs.append(f"coverage_candidate_conservation:{d}")
        if not all(_bool(r.get(x)) for x in ["candidate_count_conserved","unweighted_mass_conserved","weighted_mass_conserved"]):errs.append(f"coverage_declared_conservation_failure:{d}")
    if not cov.empty:
        cm=cov.set_index("empirical_distribution_id",drop=False).to_dict("index")
        for d,g in atoms.groupby("empirical_distribution_id",dropna=False):
            r=cm.get(d)
            if r is None:errs.append(f"atom_distribution_missing_coverage:{d}")
            elif len(g)!=int(_num(r.get("promotable_candidate_count")) or 0):errs.append(f"atom_promotable_count_mismatch:{d}")
        ac=adj.groupby("empirical_distribution_id",dropna=False).size().to_dict() if not adj.empty else {}
        for r in cov.to_dict("records"):
            if int(ac.get(r["empirical_distribution_id"],0))!=int(_num(r.get("applicable_candidate_count")) or 0):errs.append(f"adjudication_coverage_count_mismatch:{r['empirical_distribution_id']}")
    if not atoms.empty:
        sides=atoms.v551_signed_side.fillna("").astype(str).str.lower(); signed=pd.to_numeric(atoms.v551_signed_intensity,errors="coerce")
        if (~sides.isin({"positive","negative","neutral"})).any() or signed.isna().any() or (signed<-V552_EPSILON).any() or (signed>1+V552_EPSILON).any() or (sides.eq("neutral")&signed.abs().gt(V552_EPSILON)).any():errs.append("invalid_v551_canonical_signed_projection")
        for c in ["atom_contract_hash","measurement_contract_hash","v551_projection_rule_id","v551_projection_authority_hash"]:
            if atoms[c].fillna("").astype(str).str.strip().eq("").any():errs.append(f"blank_required_v551_provenance:{c}")
    return {"status":"PASS" if not errs else "BLOCKED_V552_V551_V3_INPUT_CONTRACT","errors":sorted(set(errs)),"atom_rows":len(atoms),"coverage_rows":len(cov),"adjudication_rows":len(adj),"schema_version":V552_SCHEMA_VERSION}

